SELECT /*+ S603 UI  시간별 송수신처리현황(TC별) TimeLogCntTCVO 황용길 */  ifd ,  tc ,  (    SELECT TRANSACTION_NAME    FROM TB_S60_IFTC010    WHERE TRANSACTION_CODE = tc) tcname ,  DECODE(src, 'S', '송신', 'R', '수신', '차이') src ,  sc ,  (    SELECT SYSTEM_PROCESS    FROM TB_S60_SYST020    WHERE EAI_SYSTEM_ID = sc) scname ,  tot,  t07 ,  t08 ,  t09 ,  t10 ,  t11 ,  t12 ,  t13 ,  t14 ,  t15 ,  t16 ,  t17 ,  t18 ,  t19 ,  t20 ,  t21 ,  t22 ,  t23 ,  t00 ,  t01 ,  t02 ,  t03 ,  t04 ,  t05 ,  t06FROM (    SELECT EAI_INTERFACE_ID ifd ,      TRIM(TRANSACTION_CODE) tc ,      SEND_RECEIVE_CODE src ,      UPPER(EAI_SYSTEM_ID) sc ,      NVL(DATA_COUNT, 0) AS tot ,      NVL(TIME_COUNT7, 0) AS t07 ,      NVL(TIME_COUNT8, 0) AS t08 ,      NVL(TIME_COUNT9, 0) AS t09 ,      NVL(TIME_COUNT10, 0) AS t10 ,      NVL(TIME_COUNT11, 0) AS t11 ,      NVL(TIME_COUNT12, 0) AS t12 ,      NVL(TIME_COUNT13, 0) AS t13 ,      NVL(TIME_COUNT14, 0) AS t14 ,      NVL(TIME_COUNT15, 0) AS t15 ,      NVL(TIME_COUNT16, 0) AS t16 ,      NVL(TIME_COUNT17, 0) AS t17 ,      NVL(TIME_COUNT18, 0) AS t18 ,      NVL(TIME_COUNT19, 0) AS t19 ,      NVL(TIME_COUNT20, 0) AS t20 ,      NVL(TIME_COUNT21, 0) AS t21 ,      NVL(TIME_COUNT22, 0) AS t22 ,      NVL(TIME_COUNT23, 0) AS t23 ,      NVL(TIME_COUNT0, 0) AS t00 ,      NVL(TIME_COUNT1, 0) AS t01 ,      NVL(TIME_COUNT2, 0) AS t02 ,      NVL(TIME_COUNT3, 0) AS t03 ,      NVL(TIME_COUNT4, 0) AS t04 ,      NVL(TIME_COUNT5, 0) AS t05 ,      NVL(TIME_COUNT6, 0) AS t06    FROM TB_S60_SUMM010 Summ    WHERE EAI_SEND_DATE = REPLACE(?, '-', '')      AND EAI_INTERFACE_ID LIKE ? || '%'      AND TRANSACTION_CODE LIKE ? || '%'    UNION ALL    SELECT ifd ,      tc ,      'C' src ,      '' sc ,      ABS(NVL(SUM(CASE WHEN sr='S' THEN tot*NVL(mrc, 1) ELSE tot*(-1) END), 0)) tot ,      ABS(NVL(SUM(CASE WHEN sr='S' THEN t07*NVL(mrc, 1) ELSE t07*(-1) END), 0)) t07 ,      ABS(NVL(SUM(CASE WHEN sr='S' THEN t08*NVL(mrc, 1) ELSE t08*(-1) END), 0)) t08 ,      ABS(NVL(SUM(CASE WHEN sr='S' THEN t09*NVL(mrc, 1) ELSE t09*(-1) END), 0)) t09 ,      ABS(NVL(SUM(CASE WHEN sr='S' THEN t10*NVL(mrc, 1) ELSE t10*(-1) END), 0)) t10 ,      ABS(NVL(SUM(CASE WHEN sr='S' THEN t11*NVL(mrc, 1) ELSE t11*(-1) END), 0)) t11 ,      ABS(NVL(SUM(CASE WHEN sr='S' THEN t12*NVL(mrc, 1) ELSE t12*(-1) END), 0)) t12 ,      ABS(NVL(SUM(CASE WHEN sr='S' THEN t13*NVL(mrc, 1) ELSE t13*(-1) END), 0)) t13 ,      ABS(NVL(SUM(CASE WHEN sr='S' THEN t14*NVL(mrc, 1) ELSE t14*(-1) END), 0)) t14 ,      ABS(NVL(SUM(CASE WHEN sr='S' THEN t15*NVL(mrc, 1) ELSE t15*(-1) END), 0)) t15 ,      ABS(NVL(SUM(CASE WHEN sr='S' THEN t16*NVL(mrc, 1) ELSE t16*(-1) END), 0)) t16 ,      ABS(NVL(SUM(CASE WHEN sr='S' THEN t17*NVL(mrc, 1) ELSE t17*(-1) END), 0)) t17 ,      ABS(NVL(SUM(CASE WHEN sr='S' THEN t18*NVL(mrc, 1) ELSE t18*(-1) END), 0)) t18 ,      ABS(NVL(SUM(CASE WHEN sr='S' THEN t19*NVL(mrc, 1) ELSE t19*(-1) END), 0)) t19 ,      ABS(NVL(SUM(CASE WHEN sr='S' THEN t20*NVL(mrc, 1) ELSE t20*(-1) END), 0)) t20 ,      ABS(NVL(SUM(CASE WHEN sr='S' THEN t21*NVL(mrc, 1) ELSE t21*(-1) END), 0)) t21 ,      ABS(NVL(SUM(CASE WHEN sr='S' THEN t22*NVL(mrc, 1) ELSE t22*(-1) END), 0)) t22 ,      ABS(NVL(SUM(CASE WHEN sr='S' THEN t23*NVL(mrc, 1) ELSE t23*(-1) END), 0)) t23 ,      ABS(NVL(SUM(CASE WHEN sr='S' THEN t00*NVL(mrc, 1) ELSE t00*(-1) END), 0)) t00 ,      ABS(NVL(SUM(CASE WHEN sr='S' THEN t01*NVL(mrc, 1) ELSE t01*(-1) END), 0)) t01 ,      ABS(NVL(SUM(CASE WHEN sr='S' THEN t02*NVL(mrc, 1) ELSE t02*(-1) END), 0)) t02 ,      ABS(NVL(SUM(CASE WHEN sr='S' THEN t03*NVL(mrc, 1) ELSE t03*(-1) END), 0)) t03 ,      ABS(NVL(SUM(CASE WHEN sr='S' THEN t04*NVL(mrc, 1) ELSE t04*(-1) END), 0)) t04 ,      ABS(NVL(SUM(CASE WHEN sr='S' THEN t05*NVL(mrc, 1) ELSE t05*(-1) END), 0)) t05 ,      ABS(NVL(SUM(CASE WHEN sr='S' THEN t06*NVL(mrc, 1) ELSE t06*(-1) END), 0)) t06    FROM (        SELECT Summ.EAI_INTERFACE_ID ifd ,          TRIM(Summ.TRANSACTION_CODE) tc ,          UPPER(Summ.EAI_SYSTEM_ID) sys ,          Summ.SEND_RECEIVE_CODE sr,          ifmg.MULTI_RECV_COUNT mrc ,          DATA_COUNT tot,          TIME_COUNT0 t00,          TIME_COUNT1 t01,          TIME_COUNT2 t02,          TIME_COUNT3 t03 ,          TIME_COUNT4 t04,          TIME_COUNT5 t05,          TIME_COUNT6 t06,          TIME_COUNT7 t07,          TIME_COUNT8 t08 ,          TIME_COUNT9 t09,          TIME_COUNT10 t10,          TIME_COUNT11 t11,          TIME_COUNT12 t12,          TIME_COUNT13 t13 ,          TIME_COUNT14 t14,          TIME_COUNT15 t15,          TIME_COUNT16 t16,          TIME_COUNT17 t17,          TIME_COUNT18 t18 ,          TIME_COUNT19 t19,          TIME_COUNT20 t20,          TIME_COUNT21 t21,          TIME_COUNT22 t22,          TIME_COUNT23 t23        FROM TB_S60_SUMM010 Summ ,          TB_S60_IFMG020 ifmg        WHERE Summ.EAI_INTERFACE_ID = ifmg.EAI_INTERFACE_ID(+)          AND Summ.EAI_SEND_DATE = REPLACE(?, '-', '')          AND Summ.EAI_INTERFACE_ID LIKE ? || '%'          AND Summ.TRANSACTION_CODE LIKE ? || '%' ) Summ    GROUP BY ifd , tc ) SummORDER BY ifd , tc , src 